// Normalise whatever arrived (form post, email trigger, another app) into the triage API's shape,
// then sign it with HMAC-SHA256 so the API can check it really came from us.
const crypto = require('crypto');

const src = ($json.body && typeof $json.body === 'object') ? $json.body : $json;
const payload = {
  external_id: String(src.id ?? src.messageId ?? src.external_id ?? `n8n-${$execution.id}-${$itemIndex}`),
  sender_email: String(src.from ?? src.email ?? src.sender_email ?? '').trim(),
  subject: String(src.subject ?? ''),
  body: String(src.text ?? src.message ?? src.body ?? ''),
  source: 'n8n',
};

const raw = JSON.stringify(payload);
const ts = Math.floor(Date.now() / 1000).toString();
const signature = crypto.createHmac('sha256', $env.WEBHOOK_SECRET).update(`${ts}.${raw}`).digest('hex');

return { json: { raw, ts, signature: `sha256=${signature}` } };
